/** What SOUND_MIXER_INFO reads: the mixer's names. */
typedef struct mixer_info {
    char id[16];
    char name[32];
    int modify_counter; /* Counts the changes to the levels. */
    int fillers[10];
} mixer_info;

#define SOUND_MIXER_INFO _SIOR('M', 101, mixer_info)

